// دالة توليد اختبار تجريبي شامل بأسئلة عشوائية من جميع الامتحانات (2022 - 2024)
export function generateRandomExam(questionCount = 60) {
  const allQs = [];
  EXAMS.forEach(exam => {
    exam.questions.forEach(q => {
      allQs.push({
        ...q,
        originExamTitle: exam.title,
        originSession: exam.session,
        originSubject: exam.subjectTitle
      });
    });
  });

  // Shuffle array
  const shuffled = [...allQs];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  const selected = shuffled.slice(0, Math.min(questionCount, shuffled.length)).map((q, idx) => ({
    ...q,
    id: `random_q_${idx + 1}`,
    number: idx + 1
  }));

  return {
    id: 'exam_random_simulation',
    specialtyId: 'specialty_econ_admin',
    year: 'شامل',
    subjectType: 'random',
    subjectTitle: 'امتحان شامل بأسئلة عشوائية',
    title: 'امتحان تجريبي شامل بأسئلة عشوائية من كافة الامتحانات (2022 - 2024)',
    session: 'محاكاة شاملة لكافة الدورات',
    durationMinutes: 180,
    questionsCount: selected.length,
    questions: selected
  };
}
